 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform horizontal stripes are completed by reflection across the
    # horizontal midpoint (the striped demo's missing row mirrors its partner).
    if all(len(set(row)) == 1 for row in grid):
        out = [row[:] for row in grid]
        for r in range(h):
            for c in range(w):
                if out[r][c] == 0:
                    out[r][c] = grid[h - 1 - r][c]
        return out

    # Otherwise extend constant-colored diagonal bands. Choose the diagonal
    # direction that agrees with every nonzero cell on each diagonal.
    for kind in ('diff', 'sum'):
        known = {}
        consistent = True
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v == 0:
                    continue
                d = (c - r) % h if kind == 'diff' else (r + c) % h
                if d in known and known[d] != v:
                    consistent = False
                    break
                known[d] = v
            if not consistent:
                break
        if consistent and known:
            out = [row[:] for row in grid]
            for r in range(h):
                for c in range(w):
                    if out[r][c] == 0:
                        d = (c - r) % h if kind == 'diff' else (r + c) % h
                        if d in known:
                            out[r][c] = known[d]
            return out

    return [row[:] for row in grid]

if __name__ == '__main__':
    demos = [
        ([[8,0,0,7,0,3,5,9,7],[0,8,0,0,7,0,3,5,9],[0,0,8,0,0,7,0,3,5],[0,0,0,8,0,0,7,0,3],[0,0,0,0,8,0,0,7,0],[9,0,0,0,0,8,0,0,7],[0,9,0,0,0,0,8,0,0],[6,0,9,0,0,0,0,8,0],[1,6,0,9,0,0,0,0,8]], [[8,1,6,7,9,3,5,9,7],[7,8,1,6,7,9,3,5,9],[9,7,8,1,6,7,9,3,5],[5,9,7,8,1,6,7,9,3],[3,5,9,7,8,1,6,7,9],[9,3,5,9,7,8,1,6,7],[7,9,3,5,9,7,8,1,6],[6,7,9,3,5,9,7,8,1],[1,6,7,9,3,5,9,7,8]]),
